    def _matches_with_alt_regex(
        self, scope: Scope
    ) -> tuple[Match, Scope]:
        """
        Try matching the scope against ``alt_path_regex`` (the regex for the
        toggled-trailing-slash variant of the route). Used by ``matches`` when
        ``strict_slashes=False`` and the primary regex did not match.
        """
        if scope["type"] != "http" or self.alt_path_regex is None:
            return Match.NONE, {}
        route_path = get_route_path(scope)
        match = self.alt_path_regex.match(route_path)
        if not match:
            return Match.NONE, {}
        matched_params = match.groupdict()
        for key, value in matched_params.items():
            matched_params[key] = self.param_convertors[key].convert(value)
        path_params = dict(scope.get("path_params", {}))
